WITH ValidInventory AS (SELECT *, COALESCE(quantity, 0) AS quantity_filled FROM inventory WHERE product_id IN (2, 4, 8) AND product_id = 2), agg AS (SELECT CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END AS last_restock_cohort, COUNT(*) AS inventory_count, MAX(last_restock) AS latest_last_restock FROM ValidInventory GROUP BY CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT last_restock_cohort, inventory_count FROM agg
